public override unsafe string ToString()
{
    var chars = stackalloc char[32];

    for (int i = 0; i < 4; i++)
    {
        for (int j = 7; j >= 0; j--)
        {
            uint cur = Value[i];
            cur >>= (j * 4);
            cur &= 0xF;
            chars[i * 8 + j] = k_HexToLiteral[cur];
        }
    }

    return new string(chars, 0, 32);
